for co in r['manifest']['companies']:
 for original in co['products']:
  if original['canonical_name'] in ['ARO-DUX4','ARO-DM1','ARO-MMP7','ARO-ATXN2','SRP-1005']:
   x=dict(original);x['product_id']=x.pop('inserted_product_id');x['roles']=['licensee'];x['evidence']=[b,c]+original['evidence'];products.append(x)
